package dev.aivillages.core.kernel.logistics;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static dev.aivillages.core.kernel.logistics.MobilityPolicy.*;
import static dev.aivillages.core.kernel.logistics.MobilityObservation.*;

final class MobilityPolicyTest {
    final Actor actor=new Actor(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),1,3,"minecraft:overworld");
    final Point start=p(0,0),captured=p(12,0);final Limits limits=Limits.maximum();
    Point p(double x,double z){return new Point("minecraft:overworld",x,201,z);}
    Session route(){return new Session(come(actor,captured,10,1000,limits),start);}
    Facts f(long tick,Point feet){return new Facts(tick,actor,feet,true,true,true,limits,1000);}
    @Test void capturedComeEndpointNeverTracksTheLaterPlayerPosition(){var s=route();Point laterPlayer=p(25,20);s.advance(f(11,p(1,0)),true);s.advance(f(12,p(2,0)),false);assertEquals(captured,s.goal().endpoint());assertNotEquals(laterPlayer,s.goal().endpoint());assertEquals(List.of(captured),s.goal().standing());}
    @Test void wideOwnerBoundsAreIntersectedWithAllD06Limits(){var l=new Limits(Integer.MAX_VALUE,Double.MAX_VALUE,Double.MAX_VALUE,Integer.MAX_VALUE,1);assertEquals(new Limits(600,64,1.5,8,10),l);assertEquals(610,come(actor,captured,10,Long.MAX_VALUE,l).deadline());}
    @Test void tighterInheritedAllowanceAndDeadlineAreNeverWidened(){var tight=new Limits(20,3,.5,2,30);var s=new Session(come(actor,captured,10,25,tight),start);assertEquals(Status.PROPOSE_ROUTE,s.advance(new Facts(10,actor,start,true,true,true,limits,1000),true).status());assertEquals(Blocker.TRAVEL_LIMIT,s.advance(f(11,p(4,0)),false).blocker());assertEquals(25,s.goal().deadline());}
    @Test void nonFiniteCoordinatesAndAllowancesAreRefused(){for(double x:new double[]{Double.NaN,Double.POSITIVE_INFINITY,Double.NEGATIVE_INFINITY}){assertThrows(IllegalArgumentException.class,()->p(x,0));assertThrows(IllegalArgumentException.class,()->new Limits(1,x,1,1,10));assertThrows(IllegalArgumentException.class,()->new Limits(1,1,x,1,10));}assertThrows(IllegalArgumentException.class,()->new Limits(0,1,1,1,10));assertThrows(IllegalArgumentException.class,()->new Limits(1,0,1,1,10));assertThrows(IllegalArgumentException.class,()->new Limits(1,1,1,0,10));}
    @Test void standingCandidatesAreCopiedAndNinthCandidateIsRefused(){var a=new ArrayList<>(List.of(captured));var g=storage(actor,captured,a,10,1000,limits);a.clear();assertEquals(List.of(captured),g.standing());assertThrows(UnsupportedOperationException.class,()->g.standing().clear());assertThrows(IllegalArgumentException.class,()->storage(actor,captured,Collections.nCopies(9,captured),10,1000,limits));}
    @Test void duplicateTickCannotSpendOrRepathTwice(){var s=route();var first=s.advance(f(10,start),true);assertSame(first,s.advance(f(10,p(40,0)),true));assertEquals(0,s.observation().travelBlocks());assertEquals(1,s.observation().repathProposals());}
    @Test void repathProposalsRespectTenTicksAndTighterOwnerInterval(){var s=route();assertEquals(Status.PROPOSE_ROUTE,s.advance(f(10,start),true).status());for(int t=11;t<20;t++)assertEquals(Status.MOVING,s.advance(f(t,start),true).status());assertEquals(Status.PROPOSE_ROUTE,s.advance(f(20,start),true).status());assertEquals(2,s.observation().repathProposals());var tight=new Session(come(actor,captured,10,1000,new Limits(600,64,1.5,8,25)),start);tight.advance(f(10,start),true);assertEquals(Status.MOVING,tight.advance(f(20,start),true).status());assertEquals(Status.PROPOSE_ROUTE,tight.advance(f(35,start),true).status());}
    @Test void nativeNavigationInProgressDoesNotTriggerRepeatedPathfinding(){var s=route();s.advance(f(10,start),true);for(int t=11;t<40;t++)s.advance(f(t,p((t-10)*.1,0)),false);assertEquals(1,s.observation().repathProposals());}
    @Test void elapsedClockAndTravelNeverResetAcrossDetours(){var s=route();s.advance(f(10,start),true);s.advance(f(20,p(3,4)),false);s.advance(f(30,start),true);assertEquals(10,s.observation().travelBlocks());assertEquals(20,s.observation().elapsedTicks());assertEquals(30,s.observation().lastProgressTick());assertEquals(start,s.observation().lastProgress());}
    @Test void deadlineAndBackwardsClockAreTypedBlockers(){assertEquals(Blocker.DEADLINE,route().advance(f(610,start),true).blocker());var s=route();s.advance(f(20,start),true);assertEquals(Blocker.CLOCK_INVALID,s.advance(f(19,start),true).blocker());assertThrows(IllegalArgumentException.class,()->come(actor,captured,Long.MAX_VALUE,Long.MAX_VALUE,limits));}
    @Test void changedIdentityAndControlRevisionCannotContinue(){var changed=new Actor(actor.world(),actor.principal(),actor.citizen(),actor.entity(),actor.generation(),4,actor.dimension());assertEquals(Blocker.IDENTITY_CHANGED,route().advance(new Facts(10,changed,start,true,true,true,limits,1000),true).blocker());assertEquals(Blocker.UNAUTHORIZED,route().advance(new Facts(10,actor,start,false,true,true,limits,1000),true).blocker());}
    @Test void unloadedCollisionAndDimensionFailClosedWithLastPhysicalProgress(){assertEquals(Blocker.UNLOADED,route().advance(new Facts(10,actor,start,true,false,true,limits,1000),true).blocker());assertEquals(Blocker.COLLISION,route().advance(new Facts(10,actor,start,true,true,false,limits,1000),true).blocker());assertEquals(Blocker.DIMENSION_CHANGED,route().advance(f(10,new Point("minecraft:the_nether",0,201,0)),true).blocker());}
    @Test void arrivalRequiresCurrentAuthorizationAndTighterRadius(){var s=route();assertEquals(Status.ARRIVED,s.advance(f(20,p(10.5,0)),false).status());assertEquals(Blocker.UNAUTHORIZED,route().advance(new Facts(20,actor,captured,false,true,true,limits,1000),false).blocker());var tight=new Session(come(actor,captured,10,1000,new Limits(600,64,.5,8,10)),start);assertEquals(Status.MOVING,tight.advance(f(20,p(11,0)),false).status());assertEquals(Status.ARRIVED,tight.advance(f(21,p(11.5,0)),false).status());}
    @Test void physicalNoProgressStopsAtOneHundredTicks(){var s=route();s.advance(f(10,start),true);assertEquals(Blocker.NO_PROGRESS,s.advance(f(110,start),false).blocker());assertEquals(start,s.observation().lastProgress());assertEquals(10,s.observation().lastProgressTick());}
    @Test void terminalArrivalBlockAndCancelCannotRestartOrResetBudgets(){var s=route();var arrived=s.advance(f(20,captured),false);assertSame(arrived,s.advance(f(21,start),true));assertSame(arrived,s.block(Blocker.CANCELLED));var cancelled=route();assertEquals(Blocker.CANCELLED,cancelled.block(Blocker.CANCELLED).blocker());assertEquals(Status.BLOCKED,cancelled.advance(f(20,captured),true).status());}
    @Test void unsupportedNamedLandmarksClarifyWithoutInventingAPlace(){assertEquals(PlaceDisposition.CLARIFY_UNSUPPORTED_LANDMARK,unsupportedLandmark());assertThrows(IllegalArgumentException.class,()->storage(actor,captured,List.of(),10,1000,limits));}
}
